// static.cjs — redirects to the @koromix/koffi-win32-x64 native binary
function loadStatic(pkg) {
  try {
    const path = require('path');
    const dir  = path.join(__dirname, '..', '..', '..', '@koromix', 'koffi-' + pkg);
    return require(dir);
  } catch (e) {
    return null;
  }
}
module.exports = { loadStatic };
